begin;
create temp table follow_ids(kind text,id uuid);grant select on follow_ids to authenticated;
insert into follow_ids values('tenant',gen_random_uuid()),('other_tenant',gen_random_uuid()),('writer',gen_random_uuid()),('subject',gen_random_uuid()),('fan',gen_random_uuid()),('outsider',gen_random_uuid()),('other_writer',gen_random_uuid());
insert into family_private.tenants(id,code,name,status,contact_phone,contact_email,payment_status)select id,case kind when 'tenant'then 'FOLLOW-TEST'else 'FOLLOW-OTHER'end,'اختبار المتابعة','active','+966500007701',kind||'-follow@example.invalid','waived'from follow_ids where kind in('tenant','other_tenant');
select set_config('request.jwt.claim.sub',(select user_id::text from family_private.platform_admins limit 1),true);
select public.platform_action('save',jsonb_build_object('id',id,'status','active','payment_status','waived'))from follow_ids where kind in('tenant','other_tenant');
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data)select id,'authenticated','authenticated',kind||'-follow@example.invalid',now(),jsonb_build_object('family_code',case kind when 'outsider'then 'FOLLOW-OTHER'else 'FOLLOW-TEST'end,'full_name',kind||' احمد حسن اختبار','display_name',kind||' احمد حسن اختبار','gender','male','phone',case kind when 'writer'then '+966500007701'when 'subject'then '+966500007702'when 'fan'then '+966500007703'when 'other_writer'then '+966500007705'else '+966500007704'end)from follow_ids where kind in('writer','subject','fan','outsider','other_writer');
update public.profiles set status='active',role=case when id in(select id from follow_ids where kind in('writer','other_writer'))then 'admin'else 'member'end where id in(select id from follow_ids);
update public.family_settings set journalist_approval=false where tenant_id=(select id from follow_ids where kind='tenant');

select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='fan'),true);
set local role authenticated;
do $$begin begin perform public.whole_tree('get');raise exception 'PRIVATE_TREE_LEAK';exception when raise_exception then if sqlerrm='PRIVATE_TREE_LEAK'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='writer'),true);
set local role authenticated;
select public.whole_tree('link',jsonb_build_object('owner',(select id from follow_ids where kind='writer'),'member',(select id from follow_ids where kind='subject'),'relation','father'));
select public.whole_tree('enable','{"enabled":true}');
do $$begin begin perform public.whole_tree('link',jsonb_build_object('owner',(select id from follow_ids where kind='writer'),'member',(select id from follow_ids where kind='outsider'),'relation','father'));raise exception 'CROSS_TENANT_LINK';exception when raise_exception then if sqlerrm='CROSS_TENANT_LINK'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='fan'),true);
set local role authenticated;
do $$declare x jsonb;begin x:=public.whole_tree('get');if jsonb_array_length(x->'nodes')<>4 or jsonb_array_length(x->'edges')<>1 or x->'edges'->0->>'label'<>'أب'then raise exception 'wrong complete family tree';end if;if x::text like '%@example.invalid%'or x::text like '%+966%'then raise exception 'private contact leak';end if;begin perform public.whole_tree('enable','{"enabled":false}');raise exception 'MEMBER_CHANGED_VISIBILITY';exception when raise_exception then if sqlerrm='MEMBER_CHANGED_VISIBILITY'then raise;end if;end;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from follow_ids where kind='writer'),true);
set local role authenticated;
select public.whole_tree('unlink',jsonb_build_object('owner',(select id from follow_ids where kind='writer'),'member',(select id from follow_ids where kind='subject')));
do $$begin if jsonb_array_length(public.whole_tree('get')->'edges')<>0 then raise exception 'unlink failed';end if;end$$;
reset role;
set local role anon;
select public.tenant_request('{"name":"اختبار كيان بدون شعار","email":"no-logo-test@example.invalid","phone":"+966500007788"}');
reset role;
do $$begin if not exists(select 1 from family_private.tenants where contact_email='no-logo-test@example.invalid'and logo is null and status='active')then raise exception 'optional logo stored incorrectly';end if;end$$;
select 'PASS: complete tree stays tenant-private, manager-approved links, opt-in member visibility, no contacts exposed, unlink and optional logo' result;
rollback;
